<?php
// The mailserver container presents a self-signed cert (generated by
// generate-certs.sh) signed by our own throwaway local CA, not a trusted
// public one. Skip peer verification for this LAN-only test rig.
$config['imap_conn_options'] = [
    'ssl' => [
        'verify_peer'       => false,
        'verify_peer_name'  => false,
        'allow_self_signed' => true,
    ],
];
$config['smtp_conn_options'] = [
    'ssl' => [
        'verify_peer'       => false,
        'verify_peer_name'  => false,
        'allow_self_signed' => true,
    ],
];
